use civvis::ai::{run_game, AdvancedAi, Ai, VictoryTarget, GrandStrategy, GENES};
use civvis::game::{Game, GameOptions};
struct Seat {
    ai: AdvancedAi,
    first_conquest: Option<u32>,
    first_engineering: Option<u32>,
    walled_conquest: u32,
    walled_before_engineering: u32,
    no_land_siege: u32,
    siege_not_near: u32,
    war_walled: u32,
    war_no_siege_or_queue: u32,
    war_siege_not_near: u32,
}
impl Ai for Seat {
    fn uses_player_observation(&self) -> bool { self.ai.uses_player_observation() }
    fn take_turn(&mut self, g: &mut Game, pid: usize) {
        let turn = g.turn;
        if g.players[pid].techs.contains(&civvis::name!("engineering")) { self.first_engineering.get_or_insert(turn); }
        self.ai.take_turn(g, pid);
        if let Some(plan) = self.ai.current_plan() {
            if plan.strategy == GrandStrategy::Conquest {
                self.first_conquest.get_or_insert(turn);
                if plan.target_city.and_then(|cid| g.cities.get(&cid)).is_some_and(|city| city.owner != pid && city.wall_hp > 0) {
                    self.walled_conquest += 1;
                    let city = &g.cities[&plan.target_city.unwrap()];
                    let siege: Vec<_> = g.units.values().filter(|unit| {
                        let spec = &g.rules.units[unit.kind];
                        unit.owner == pid && spec.class == "military" && spec.siege
                            && !matches!(spec.domain.as_deref(), Some("sea" | "air"))
                    }).collect();
                    if g.is_at_war(pid, city.owner) {
                        self.war_walled += 1;
                        let queued = g.cities.values().filter(|c| c.owner == pid).any(|c| c.queue.iter().any(|item| {
                            if let civvis::game::Item::Unit { unit } = item {
                                let spec = &g.rules.units[*unit];
                                spec.class == "military" && spec.siege && !matches!(spec.domain.as_deref(), Some("sea" | "air"))
                            } else { false }
                        }));
                        if siege.is_empty() && !queued { self.war_no_siege_or_queue += 1; }
                        if !siege.is_empty() && !siege.iter().any(|unit| g.wdist(unit.pos, city.pos) <= 6) { self.war_siege_not_near += 1; }
                    }
                    if siege.is_empty() { self.no_land_siege += 1; }
                    else if !siege.iter().any(|unit| g.wdist(unit.pos, city.pos) <= 6) { self.siege_not_near += 1; }
                    if !g.players[pid].techs.contains(&civvis::name!("engineering")) { self.walled_before_engineering += 1; }
                }
            }
        }
    }
}
fn main() {
    for seed in 109106000..109106008 {
        let mut g=Game::new_with(GameOptions{barbarians:false,speed:"online".into(),..GameOptions::new(3,36,22,seed,250,0)});
        let mut ais:Vec<_>=AdvancedAi::fleet_targeting(&g,VictoryTarget::Domination).into_iter().map(|mut ai| {
            (GENES.iter().find(|gene|gene.tag=="domination-lane-hands-over").unwrap().enable)(&mut ai);
            (GENES.iter().find(|gene|gene.tag=="domination-siege-research").unwrap().disable)(&mut ai);
            Seat{ai,first_conquest:None,first_engineering:None,walled_conquest:0,walled_before_engineering:0,no_land_siege:0,siege_not_near:0,war_walled:0,war_no_siege_or_queue:0,war_siege_not_near:0}
        }).collect();
        run_game(&mut g,&mut ais);
        for (pid,seat) in ais.iter().enumerate() {
            println!("{seed} p{pid} first_conquest={:?} engineering={:?} walled_conquest={} before_engineering={} no_land_siege={} siege_not_near={} war_walled={} war_no_siege_or_queue={} war_siege_not_near={}",seat.first_conquest,seat.first_engineering,seat.walled_conquest,seat.walled_before_engineering,seat.no_land_siege,seat.siege_not_near,seat.war_walled,seat.war_no_siege_or_queue,seat.war_siege_not_near);
        }
        println!("END {seed} {:?} {:?} {}",g.victory_type,g.winner,g.turn);
    }
}
